          return result.getTotalTimeMillis() >= 0;
        });
  }

  private static void test(String name, TestCase testCase) {
    try {
      if (testCase.run()) {
        System.out.println("  ✓ " + name);
        testsPassed++;
      } else {
        System.out.println("  ✗ " + name);
        testsFailed++;
      }
